patches.new:
:root { --red: #aa3741; --line: #dfdbd6; --muted: #635f5a; }
body { width: calc(100% - 32px); max-width: 800px; min-width: 0; background: #f6f5f2; color: #302d2b; font-weight: 400; }
.todoapp { margin: 124px 0 0; border: 1px solid var(--line); border-radius: 10px; box-shadow: 0 3px 0 -1px #ece9e4, 0 10px 28px #3129230c; }
.todoapp h1 { top: auto; bottom: calc(100% + 16px); left: 0; margin: 0; font-size: 66px; line-height: 1; letter-spacing: -3px; text-align: left; }
.header { padding: 20px 24px 24px; }
.entry { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; }
.entry label { grid-column: 1 / -1; font-size: 15px; font-weight: 600; }
.new-todo { height: 48px; padding: 8px 14px; border: 1px solid #aca7a2; border-radius: 5px; box-shadow: none; font-size: 18px; }
.todoapp .new-todo::placeholder { color: #726d68; font-style: normal; }
.entry button { background: var(--red); color: white; padding: 0 22px; border-radius: 5px; font-weight: 600; }
button, .toggle-all-label { cursor: pointer; }
.toggle-all-container { display: flex; align-items: center; flex-wrap: wrap; gap: 4px 12px; padding: 6px 16px; background: #f9f8f6; border-bottom: 1px solid var(--line); }
.toggle-all { right: auto; bottom: auto; }
.toggle-all + label { position: static; width: auto; height: 44px; font-size: 14px; gap: 8px; color: var(--muted); }
.toggle-all + label:before { content: ''; padding: 0; width: 16px; height: 16px; border: 1px solid currentColor; border-radius: 4px; transform: none; text-align: center; line-height: 16px; font-size: 14px; }
.toggle-all:checked + label:before { content: '✓'; color: white; background: #287268; }
.filters { position: static; margin-left: auto; display: flex; }
.filters li a { display: flex; align-items: center; min-height: 44px; box-sizing: border-box; padding: 0 12px; margin: 0; font-weight: 500; }
.filters li a.selected { color: var(--red); background: #faeaeb; border-color: #dbb6b8; font-weight: 600; }
.todo-list .view { display: grid; grid-template-columns: 44px minmax(0,1fr) auto auto; align-items: center; gap: 4px; padding: 6px 16px 6px 10px; min-height: 46px; }
.todo-list li .toggle { position: static; width: 44px; height: 44px; margin: 0; opacity: 1; cursor: pointer; display: grid; place-items: center; }
.toggle:before { content: ''; width: 21px; height: 21px; border: 1.5px solid #918b85; border-radius: 50%; }
.toggle:checked:before { content: '✓'; background: #287268; border-color: #287268; color: white; font: bold 16px/21px Arial, sans-serif; }
.todo-list li .toggle + label, .todo-list li .toggle:checked + label { background: none; }
.todo-list li label { word-break: normal; overflow-wrap: anywhere; padding: 5px 8px 5px 0; font-size: 18px; line-height: 1.45; color: #302d2b; }
.todo-list li.completed { background: #f7f9f7; }
.todo-list li.completed label { color: #626d68; }
.todo-list li .destroy, .edit-task { display: block; position: static; width: auto; min-width: 44px; height: 44px; padding: 0 5px; font-size: 14px; color: var(--red); }
.edit-task { color: var(--muted); }
.todo-list li .destroy:after, .footer:before { display: none; }
.todo-list li.editing { padding: 9px 16px; }
.todo-list li.editing .edit { margin: 0; width: 100%; padding: 9px 12px; border-radius: 4px; font-size: 18px; }
.footer { height: auto; padding: 5px 20px; text-align: right; color: var(--muted); }
.footer:after { content: ''; display: block; clear: both; }
.todo-count { line-height: 44px; }
.todo-count strong { font-weight: 650; }
.clear-completed { min-height: 44px; color: var(--red); }
.no-matches { padding: 18px 22px; }
.no-matches a { color: var(--red); }
.todo-list:not(:empty) + .no-matches { display: none; }
.info { display: flex; flex-wrap: wrap; justify-content: center; gap: 5px 14px; margin: 24px auto; color: var(--muted); font-size: 12px; }
.info p { margin: 0; line-height: 1.5; }
.info p:first-child { flex-basis: 100%; }
.info a { text-decoration: underline; }
:focus-visible, .toggle-all:focus-visible + label { outline: 2px solid var(--red); outline-offset: 2px; }
@media (max-width: 520px) {
 body { width: calc(100% - 24px); }
 .todoapp { margin-top: 84px; }
 .todoapp h1 { font-size: 50px; bottom: calc(100% + 10px); }
 .header { padding: 14px; }
 .entry button { padding: 0 16px; }
 .toggle-all-container { padding: 4px 10px; }
 .filters li a { padding: 0 8px; }
 .todo-list .view { padding-inline: 3px 7px; gap: 1px; }
 .todo-list li label { font-size: 17px; }
 .footer { padding-inline: 14px; }
}
